parameters.jsCode:
const items = $input.all();

for (const item of items) {
  const body = item.json.body || item.json;

  const cardId = body.cardId;
  const title = body.title;
  const bodyText = body.bodyText || "";
  const imageUrl = body.imageUrl || "";
  const videoUrl = body.videoUrl || "";
  const scheduledDate = body.scheduledDate; // YYYY-MM-DD
  const scheduledTime = body.scheduledTime; // HH:MM

  const integration = body.integration || {};
  const pageId = integration.pageId || body.pageId;
  const accessToken = integration.pageAccessToken || body.accessToken;

  if (!pageId || !accessToken) {
    throw new Error("Missing Facebook Page ID or Access Token in integration data.");
  }

  // 1. Kiểm tra xem có phải là bài đăng lên lịch hay đăng ngay lập tức
  const isScheduled = scheduledDate && scheduledTime;
  let scheduledPublishTime = null;

  if (isScheduled) {
    // Chuyển đổi ngày giờ Việt Nam sang UNIX timestamp
    const dateStr = `${scheduledDate}T${scheduledTime}:00+07:00`;
    const dateObj = new Date(dateStr);
    if (isNaN(dateObj.getTime())) {
      throw new Error(`Invalid scheduled date or time: ${scheduledDate} ${scheduledTime}`);
    }
    scheduledPublishTime = Math.floor(dateObj.getTime() / 1000);
  }

  // 2. Xác định Endpoint và Body của Facebook Graph API dựa trên loại media và hình thức đăng
  let facebookApiUrl = "";
  let requestBody = {};
  let postType = "text";

  if (videoUrl && videoUrl.trim().startsWith("http")) {
    postType = "video";
    facebookApiUrl = `https://graph.facebook.com/v19.0/${pageId}/videos`;
    requestBody = {
      description: bodyText,
      file_url: videoUrl,
      access_token: accessToken
    };
    if (isScheduled) {
      requestBody.published = false;
      requestBody.scheduled_publish_time = scheduledPublishTime;
    } else {
      requestBody.published = true;
    }
  } else if (imageUrl && imageUrl.trim().startsWith("http")) {
    postType = "image";
    facebookApiUrl = `https://graph.facebook.com/v19.0/${pageId}/photos`;
    requestBody = {
      caption: bodyText,
      url: imageUrl,
      access_token: accessToken
    };
    if (isScheduled) {
      requestBody.published = false;
      requestBody.scheduled_publish_time = scheduledPublishTime;
    } else {
      requestBody.published = true;
    }
  } else {
    postType = "text";
    facebookApiUrl = `https://graph.facebook.com/v19.0/${pageId}/feed`;
    requestBody = {
      message: bodyText,
      access_token: accessToken
    };
    if (isScheduled) {
      requestBody.published = false;
      requestBody.scheduled_publish_time = scheduledPublishTime;
    }
  }

  item.json.preparedData = {
    cardId,
    postType,
    apiUrl: facebookApiUrl,
    body: requestBody
  };
}

return items;

